/** OBJ+MTL and binary glTF 2.0 (GLB) writers for meshes generated by renderer-3d. Units: meters, Y-up. */
import type { MeshPart } from '../../renderer-3d/src/mesh';

export function toOBJ(parts: MeshPart[], name = 'planforge'): { obj: string; mtl: string } {
  const mats = new Map<string, MeshPart['color']>();
  const matName = (c: MeshPart['color']) => {
    const k = `m_${c.map((x) => Math.round(x * 255).toString(16).padStart(2, '0')).join('')}`;
    mats.set(k, c); return k;
  };
  const o: string[] = [`# PlanForge Studio OBJ export (meters, Y-up)`, `mtllib ${name}.mtl`];
  let base = 1;
  for (const p of parts) {
    o.push(`o ${p.kind}_${p.id.slice(0, 8)}`, `usemtl ${matName(p.color)}`);
    for (let i = 0; i < p.positions.length; i += 3) o.push(`v ${p.positions[i].toFixed(5)} ${p.positions[i + 1].toFixed(5)} ${p.positions[i + 2].toFixed(5)}`);
    for (let i = 0; i < p.normals.length; i += 3) o.push(`vn ${p.normals[i].toFixed(4)} ${p.normals[i + 1].toFixed(4)} ${p.normals[i + 2].toFixed(4)}`);
    for (let i = 0; i < p.indices.length; i += 3) {
      const [a, b, c] = [p.indices[i] + base, p.indices[i + 1] + base, p.indices[i + 2] + base];
      o.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
    }
    base += p.positions.length / 3;
  }
  const mtl = [...mats].map(([k, c]) => `newmtl ${k}\nKd ${c[0].toFixed(4)} ${c[1].toFixed(4)} ${c[2].toFixed(4)}\nd ${c[3].toFixed(3)}\nillum 1\n`).join('\n');
  return { obj: o.join('\n') + '\n', mtl };
}

export function toGLB(parts: MeshPart[]): Uint8Array {
  const usable = parts.filter((p) => p.indices.length);
  const chunks: Uint8Array[] = [];
  let offset = 0;
  const bufferViews: object[] = [], accessors: object[] = [], meshes: object[] = [], nodes: number[] = [], materials: object[] = [];
  const matIndex = new Map<string, number>();
  const push = (arr: ArrayBufferView, target: number) => {
    const bytes = new Uint8Array(arr.buffer, arr.byteOffset, arr.byteLength);
    const pad = (4 - (bytes.byteLength % 4)) % 4;
    chunks.push(bytes); if (pad) chunks.push(new Uint8Array(pad));
    bufferViews.push({ buffer: 0, byteOffset: offset, byteLength: bytes.byteLength, target });
    offset += bytes.byteLength + pad;
    return bufferViews.length - 1;
  };
  for (const p of usable) {
    const pos = new Float32Array(p.positions), nor = new Float32Array(p.normals), idx = new Uint32Array(p.indices);
    const min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
    for (let i = 0; i < pos.length; i += 3) for (let k = 0; k < 3; k++) { min[k] = Math.min(min[k], pos[i + k]); max[k] = Math.max(max[k], pos[i + k]); }
    const vp = push(pos, 34962), vn = push(nor, 34962), vi = push(idx, 34963);
    accessors.push({ bufferView: vp, componentType: 5126, count: pos.length / 3, type: 'VEC3', min, max });
    accessors.push({ bufferView: vn, componentType: 5126, count: nor.length / 3, type: 'VEC3' });
    accessors.push({ bufferView: vi, componentType: 5125, count: idx.length, type: 'SCALAR' });
    const mk = p.color.join(',');
    if (!matIndex.has(mk)) {
      materials.push({ pbrMetallicRoughness: { baseColorFactor: p.color, metallicFactor: 0, roughnessFactor: 0.85 }, alphaMode: p.color[3] < 1 ? 'BLEND' : 'OPAQUE', doubleSided: true });
      matIndex.set(mk, materials.length - 1);
    }
    const a = accessors.length;
    meshes.push({ name: `${p.kind}_${p.id}`, primitives: [{ attributes: { POSITION: a - 3, NORMAL: a - 2 }, indices: a - 1, material: matIndex.get(mk) }] });
    nodes.push(meshes.length - 1);
  }
  const json = {
    asset: { version: '2.0', generator: 'PlanForge Studio' },
    scene: 0, scenes: [{ nodes: nodes.map((_, i) => i) }],
    nodes: nodes.map((m) => ({ mesh: m })), meshes, materials, accessors, bufferViews,
    buffers: [{ byteLength: offset }],
  };
  const enc = new TextEncoder().encode(JSON.stringify(json));
  const jsonPad = (4 - (enc.byteLength % 4)) % 4;
  const jsonLen = enc.byteLength + jsonPad;
  const total = 12 + 8 + jsonLen + 8 + offset;
  const out = new Uint8Array(total);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, 0x46546c67, true); dv.setUint32(4, 2, true); dv.setUint32(8, total, true);
  dv.setUint32(12, jsonLen, true); dv.setUint32(16, 0x4e4f534a, true);
  out.set(enc, 20); for (let i = 0; i < jsonPad; i++) out[20 + enc.byteLength + i] = 0x20;
  let p = 20 + jsonLen;
  dv.setUint32(p, offset, true); dv.setUint32(p + 4, 0x004e4942, true); p += 8;
  for (const c of chunks) { out.set(c, p); p += c.byteLength; }
  return out;
}

/** Parse a GLB container and return its JSON + binary chunk (used by validation tests). */
export function readGLB(bytes: Uint8Array) {
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (dv.getUint32(0, true) !== 0x46546c67) throw new Error('Not a GLB');
  if (dv.getUint32(8, true) !== bytes.byteLength) throw new Error('Length mismatch');
  const jl = dv.getUint32(12, true);
  if (dv.getUint32(16, true) !== 0x4e4f534a) throw new Error('First chunk must be JSON');
  const json = JSON.parse(new TextDecoder().decode(bytes.subarray(20, 20 + jl)));
  const bl = dv.getUint32(20 + jl, true);
  if (dv.getUint32(24 + jl, true) !== 0x004e4942) throw new Error('Second chunk must be BIN');
  return { json, bin: bytes.subarray(28 + jl, 28 + jl + bl) };
}
